<h2>Calculate ROAS and a gross-margin break-even reference</h2><p class="lead">Compare attributed revenue with ad spend and optionally include gross margin for a simplified contribution view.</p><div class="form-grid"><div class="field"><label for="rev">Attributed revenue</label><input id="rev" type="number" min="0" step="0.01" value="12500"></div><div class="field"><label for="spend">Ad spend</label><input id="spend" type="number" min="0" step="0.01" value="3500"></div><div class="field full"><label for="margin">Gross margin (%)</label><input id="margin" type="number" min="0.01" max="100" step="0.01" value="60"><small>Optional simplified reference. Enter gross margin before advertising expense.</small></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc">Calculate</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>ROAS</span><strong id="roas">—</strong></div><div class="metric"><span>Break-even ROAS*</span><strong id="be">—</strong></div><div class="metric"><span>Gross contribution after ad spend*</span><strong id="contrib">—</strong></div></div><p class="helper">*Simplified gross-margin model only; excludes overhead, fees, returns, taxes and other costs.</p></div>
<script>(()=>{const $=i=>document.getElementById(i),n=i=>parseFloat($(i).value)||0;function go(){const r=n('rev'),s=n('spend'),m=n('margin')/100;$('roas').textContent=s>0?(r/s).toFixed(2)+'×':'—';$('be').textContent=m>0?(1/m).toFixed(2)+'×':'—';$('contrib').textContent=m>0?'$'+(r*m-s).toLocaleString(undefined,{maximumFractionDigits:2,minimumFractionDigits:2}):'—'}document.querySelectorAll('input').forEach(x=>x.addEventListener('input',go));$('calc').onclick=go;go()})();</script>
